css:
@keyframes fxhh-a{to{background-size:100% var(--h,62%)}}@keyframes fxhh-b{to{background-size:100% var(--h,62%)}}
.fx-hhl{width:min(900px,100%);display:grid;gap:1.6em;text-align:center;justify-items:center}
.fx-hhl .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;opacity:.6}
.fx-hhl h1{font-size:clamp(2.3em,5.8vw,4.4em);line-height:1.22;max-width:14em}
.fx-hhl mark{--c:color-mix(in srgb,var(--accent) 48%,transparent);color:inherit;padding:0 .14em;margin:0 -.04em;background:linear-gradient(var(--c),var(--c)) 0 90%/0 var(--h,62%) no-repeat;-webkit-box-decoration-break:clone;box-decoration-break:clone;border-radius:.12em;animation:fxhh-a calc(.9s/var(--speed)) cubic-bezier(.6,.1,.2,1) .5s forwards}
.fx-hhl mark:hover{animation-name:fxhh-b}
.fx-hhl mark.p{--c:color-mix(in srgb,var(--primary) 30%,transparent);animation-delay:1.2s}
.fx-hhl mark.thin{--h:30%;--c:color-mix(in srgb,var(--accent) 70%,transparent);background-position:0 96%;animation-delay:1.9s}
.fx-hhl p{font-size:1.15em;line-height:1.9;max-width:36em;opacity:.85}
.fx-hhl p mark{animation-delay:2.4s;--c:color-mix(in srgb,var(--primary) 24%,transparent)}
.fx-hhl small{opacity:.5;font-size:.85em}
@media(prefers-reduced-motion:reduce){.fx-hhl mark{animation:none;background-size:100% var(--h,62%)}}
/* touch: :hover mirrored as .is-tap */
.fx-hhl mark.is-tap{animation-name:fxhh-b}
